package com.aoo.bcg.wordcard;
import com.aoo.bcg.gamespi.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class YzchzGameProviderTest{
 @Test void creationJoinReadyStartOperationRotationReconnectSettlementAndReplay(){YzchzGameProvider p=new YzchzGameProvider();YzchzSession s=(YzchzSession)p.roomFactory().create(new RoomCreationContext(9342,10,Map.of("playerCount",3,"wangCount",4,"piaoCap",4,"genXing",true))).requireAuthoritativeSession();s.execute(c(1,1,"20",Map.of("action","join")));s.execute(c(2,2,"30",Map.of("action","join")));s.execute(c(3,1,"20",Map.of("action","piao","piao",2)));s.execute(c(4,1,"20",Map.of("action","ready")));s.execute(c(5,2,"30",Map.of("action","ready")));s.execute(c(6,0,"10",Map.of("action","start")));Map<String,Object>before=s.authoritativeState();int offset=s.events().size();Map<Integer,Object>seats=(Map<Integer,Object>)s.viewFor(10).get("seats");List<?>owner=(List<?>)((Map<?,?>)seats.get(0)).get("cards");s.execute(c(7,0,"10",Map.of("action","operation","payload",Map.of("operation","DISCARD","cards",List.of(owner.getFirst())))));List<?>hand=(List<?>)((Map<?,?>)((Map<?,?>)s.viewFor(20).get("seats")).get(1)).get("cards");s.execute(c(8,1,"20",Map.of("action","operation","payload",Map.of("operation","TI","cards",hand.subList(0,4)))));s.execute(c(9,1,"20",Map.of("action","operation","payload",Map.of("operation","HU"))));assertEquals("FINISHED",s.viewFor(20).get("phase"));assertNotNull(s.viewFor(20).get("waitInfo"));Map<?,?>seat=(Map<?,?>)((Map<?,?>)s.viewFor(20).get("seats")).get(1);assertFalse(((List<?>)seat.get("publicGroups")).isEmpty());assertTrue(((Number)seat.get("lockedHuXi")).intValue()>0);assertEquals(9342,s.settlement(1,"1.0.0").roomId());AuthoritativeGameSession restored=p.restoreAuthoritativeSession(s.authoritativeState()).orElseThrow();assertEquals(s.viewFor(20),restored.viewFor(20));StatePayload replayed=p.eventReplayProvider().orElseThrow().replay(StatePayload.copyOf(before),s.events().subList(offset,s.events().size()));assertEquals(s.authoritativeState(),replayed.asMap());assertTrue(p.ruleComponents().getFirst().execute(c(10,1,"20",Map.of("action","state"))).accepted());}
 @Test void settlementUsesTheSameAuthoritativeHuXiGateAsHu(){YzchzGameProvider p=new YzchzGameProvider();YzchzSession s=(YzchzSession)p.roomFactory().create(new RoomCreationContext(9342,10,Map.of("playerCount",3,"wangCount",4,"piaoCap",4,"genXing",true))).requireAuthoritativeSession();s.execute(c(1,1,"20",Map.of("action","join")));s.execute(c(2,2,"30",Map.of("action","join")));s.execute(c(3,1,"20",Map.of("action","ready")));s.execute(c(4,2,"30",Map.of("action","ready")));s.execute(c(5,0,"10",Map.of("action","start")));Map<String,Object>state=new LinkedHashMap<>(s.authoritativeState());Map<String,Object>game=new LinkedHashMap<>((Map<String,Object>)state.get("game"));game.put("phase","FINISHED");game.put("winner",1);game.put("huXi",Map.of(0,0,1,14,2,0));state.put("game",Map.copyOf(game));state.put("lockedHuXi",Map.of(0,0,1,0,2,0));YzchzSession invalid=(YzchzSession)p.restoreAuthoritativeSession(state).orElseThrow();assertTrue(invalid.invariantViolations().contains("WINNER_HU_XI_BELOW_15"));assertThrows(IllegalStateException.class,()->invalid.settlement(1,"1.0.0"));}
 private static GameCommandRequest c(long n,int seat,String user,Map<String,Object>b){return new GameCommandRequest("wordcard.yzchz.dispatch","r"+n,n,9342,0,"1.0.0",user,seat,b);}
}
